package vn.vinhkhang.warehouse;
import java.util.*;import java.math.*;import java.time.*;import java.security.*;
import org.springframework.web.bind.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.ObjectMapper;
@RestController @RequestMapping("/api/sales-transfer")
public class SalesTransfer {
 final Api core;final JdbcTemplate db;final ObjectMapper json;
 public SalesTransfer(Api core,JdbcTemplate db,ObjectMapper json){this.core=core;this.db=db;this.json=json;}
 @ExceptionHandler(Api.Problem.class) public org.springframework.http.ResponseEntity<?> problem(Api.Problem e){return org.springframework.http.ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
 @ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class) public org.springframework.http.ResponseEntity<?> conflict(Exception e){return org.springframework.http.ResponseEntity.status(409).body(Map.of("message","Phiếu đã nhận hoặc dữ liệu không hợp lệ. Chưa nhập thêm doanh số nào."));}
 static Map<String,Object> lower(Map<String,Object> row,String... keys){var out=new LinkedHashMap<String,Object>();for(String key:keys)out.put(key.toLowerCase(Locale.ROOT),row.get(key));return out;}
 @PostMapping("/export") @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) public Object export(@RequestHeader("Authorization") String token,@RequestBody Map<String,Object> body){core.admin(token);if(!(body.get("ids") instanceof List<?> raw)||raw.isEmpty()||raw.size()>1000)throw new Api.Problem(400,"Chọn từ 1 đến 1000 phiếu xuất cho khách");var ids=new TreeSet<Long>();for(Object value:raw){long id=Long.parseLong(value.toString());if(id<=0||!ids.add(id))throw new Api.Problem(400,"Phiếu bị trùng hoặc không hợp lệ");}
 var sales=new ArrayList<Map<String,Object>>();for(long id:ids){var found=db.queryForList("SELECT * FROM vehicle_shipments WHERE id=? AND deleted=FALSE",id);if(found.isEmpty())throw new Api.Problem(409,"Phiếu xuất đã thay đổi");var h=found.getFirst();if(!"SALE".equals(h.get("SHIPMENT_PURPOSE")))throw new Api.Problem(409,"Chỉ chuyển doanh số phiếu Xuất cho khách; nội bộ, ký gửi và Trả NCC không tính doanh số");var report=db.queryForList("SELECT * FROM revenue_sales WHERE source_type='VEHICLE' AND source_id=? AND deleted=FALSE",id);if(report.isEmpty())throw new Api.Problem(409,"Phiếu "+h.get("CODE")+" chưa đủ thông tin doanh số; anh bổ sung thông tin bán hàng trước");var sale=report.getFirst();long sid=((Number)sale.get("ID")).longValue();var item=new LinkedHashMap<String,Object>();item.put("transfer_uuid",h.get("TRANSFER_UUID"));item.put("source_code",h.get("CODE"));item.put("shipment_purpose","SALE");item.put("sale",lower(sale,"CHANNEL","PARTY_CODE","PARTY_NAME","PHONE","PROVINCE","SALE_DATE","TRANSPORT_COST","TRANSPORT_FEE"));
 item.put("lines",db.queryForList("SELECT * FROM revenue_lines WHERE sale_id=? ORDER BY id",sid).stream().map(l->lower(l,"ITEM_CODE","ITEM_NAME","CATEGORY","QUANTITY","UNIT_PRICE","FACTORY_UNIT_COST","DISCOUNT","SUPPORT","ITEM_UNIT")).toList());
 item.put("entries",db.queryForList("SELECT * FROM revenue_entries WHERE sale_id=? AND deleted=FALSE ORDER BY id",sid).stream().map(e->lower(e,"KIND","ENTRY_DATE","AMOUNT","NOTE")).toList());sales.add(item);}
 return Map.of("format","vinhkhang-sales-transfer","version",1,"exported_at",Instant.now().toString(),"sales",sales);
 }
 @SuppressWarnings("unchecked") Map<String,Object> map(Object value){if(!(value instanceof Map<?,?>))throw new Api.Problem(400,"File doanh số không đúng định dạng");return (Map<String,Object>)value;}
 List<Map<String,Object>> validate(Map<String,Object> packet){if(!"vinhkhang-sales-transfer".equals(packet.get("format"))||!"1".equals(Objects.toString(packet.get("version"))))throw new Api.Problem(400,"Chọn đúng file doanh số Vĩnh Khang phiên bản 1");var records=core.lines(packet,"sales");var seen=new HashSet<String>();for(var item:records){String key=core.str(item,"transfer_uuid");try{UUID.fromString(key);}catch(Exception e){throw new Api.Problem(400,"Mã chuyển phiếu không hợp lệ");}if(!seen.add(key)||!"SALE".equals(item.get("shipment_purpose")))throw new Api.Problem(400,"File có phiếu trùng hoặc phiếu không phải xuất bán");RevenueReports.text(item,"source_code",100,true);var sale=map(item.get("sale"));String channel=RevenueReports.text(sale,"channel",10,true);if(!Set.of("STORE","DEALER").contains(channel))throw new Api.Problem(400,"Loại khách không hợp lệ");for(String field:List.of("party_code","party_name","phone","province"))RevenueReports.text(sale,field,field.equals("party_code")?80:field.equals("phone")?100:200,Set.of("party_code","party_name").contains(field));LocalDate date=RevenueReports.day(sale.get("sale_date"));if(date.isAfter(LocalDate.now()))throw new Api.Problem(400,"Ngày bán không được sau hôm nay");BigDecimal net=BigDecimal.ZERO;for(var line:core.lines(item,"lines")){RevenueReports.text(line,"item_code",100,true);RevenueReports.text(line,"item_name",500,true);RevenueReports.text(line,"item_unit",100,true);if(!Set.of("TM","DK","LK").contains(line.get("category")))throw new Api.Problem(400,"Loại hàng không hợp lệ");BigDecimal quantity=core.dec(line,"quantity"),price=RevenueReports.money(line,"unit_price",false),discount=SalesFlow.amount(line,"discount"),support=SalesFlow.amount(line,"support");Costing.cost(line,"factory_unit_cost");if(!"LK".equals(line.get("category"))&&quantity.stripTrailingZeros().scale()>0)throw new Api.Problem(400,"Số xe phải là số nguyên");if(channel.equals("STORE")&&(discount.signum()!=0||support.signum()!=0))throw new Api.Problem(400,"Chiết khấu và hỗ trợ chỉ dành cho đại lý");BigDecimal value=quantity.multiply(price).setScale(2,RoundingMode.HALF_UP).subtract(discount).subtract(support);if(value.signum()<0)throw new Api.Problem(400,"Chiết khấu/hỗ trợ vượt tiền bán");net=net.add(value);}
 SalesFlow.amount(sale,"transport_cost");net=net.add(SalesFlow.amount(sale,"transport_fee"));Object entries=item.get("entries");if(!(entries instanceof List<?> list)||list.size()>1000)throw new Api.Problem(400,"Lịch sử thu/chi không hợp lệ");BigDecimal paid=BigDecimal.ZERO;for(Object raw:list){var entry=map(raw);String kind=RevenueReports.text(entry,"kind",10,true);if(!Set.of("PAYMENT","CSKH").contains(kind)||kind.equals("CSKH")&&!channel.equals("STORE"))throw new Api.Problem(400,"Loại thu/chi không hợp lệ");if(RevenueReports.day(entry.get("entry_date")).isBefore(date))throw new Api.Problem(400,"Thu/chi trước ngày bán");BigDecimal amount=RevenueReports.money(entry,"amount",false);if(amount.signum()<=0)throw new Api.Problem(400,"Số tiền thu/chi phải lớn hơn 0");RevenueReports.text(entry,"note",500,true);if(kind.equals("PAYMENT"))paid=paid.add(amount);}if(paid.compareTo(net)>0)throw new Api.Problem(400,"Tiền đã thu vượt doanh thu thuần");}
 return records;
 }
 void access(String token){var user=core.admin(token);if(!AccountKinds.get(db,user.id()).equals("STORE"))throw new Api.Problem(403,"Nhận doanh số dành cho tài khoản cửa hàng");}
 @PostMapping("/preview") @Transactional(readOnly=true) public Object preview(@RequestHeader("Authorization") String token,@RequestBody Map<String,Object> packet){access(token);var items=new ArrayList<Map<String,Object>>();for(var item:validate(packet)){var sale=map(item.get("sale"));var lines=core.lines(item,"lines");BigDecimal gross=BigDecimal.ZERO,net=BigDecimal.ZERO,quantity=BigDecimal.ZERO;for(var l:lines){BigDecimal value=core.dec(l,"quantity").multiply(RevenueReports.money(l,"unit_price",false));gross=gross.add(value);net=net.add(value.subtract(SalesFlow.amount(l,"discount")).subtract(SalesFlow.amount(l,"support")));if(!l.get("category").equals("LK"))quantity=quantity.add(core.dec(l,"quantity"));}net=net.add(SalesFlow.amount(sale,"transport_fee"));var summary=new LinkedHashMap<String,Object>(Map.of("transfer_uuid",item.get("transfer_uuid"),"source_code",item.get("source_code"),"party_name",sale.get("party_name"),"channel",sale.get("channel"),"sale_date",sale.get("sale_date"),"vehicles",quantity,"gross",gross,"net",net,"received",db.queryForObject("SELECT COUNT(*) FROM sales_transfers WHERE transfer_uuid=?",Integer.class,item.get("transfer_uuid"))>0));BigDecimal cost=BigDecimal.ZERO;boolean known=true;for(var line:lines){BigDecimal c=Costing.cost(line,"factory_unit_cost");if(c==null)known=false;else cost=cost.add(core.dec(line,"quantity").multiply(c));}summary.put("cost",known?cost:null);summary.put("goods",lines.stream().map(l->l.get("item_name").toString()).collect(java.util.stream.Collectors.joining(" / ")));items.add(summary);}return Map.of("items",items,"note","Chỉ ghi báo cáo doanh số, không nhập xe, không nhập linh kiện và không thay đổi tồn kho cửa hàng.");}
 @PostMapping("/import") @Transactional public Object receive(@RequestHeader("Authorization") String token,@RequestBody Map<String,Object> body){access(token);if(!"NHAN DOANH SO".equals(body.get("confirmation")))throw new Api.Problem(400,"Xác nhận nhận doanh số");var packet=map(body.get("packet"));var all=validate(packet);if(!(body.get("selected") instanceof List<?> values)||values.isEmpty()||values.size()>1000)throw new Api.Problem(400,"Chọn phiếu muốn nhận");var selected=new HashSet<String>();for(Object value:values)if(!selected.add(value.toString()))throw new Api.Problem(400,"Phiếu bị chọn trùng");if(!all.stream().map(i->i.get("transfer_uuid").toString()).collect(java.util.stream.Collectors.toSet()).containsAll(selected))throw new Api.Problem(400,"Phiếu không thuộc file");var actor=core.admin(token);int count=0;for(var item:all){String key=item.get("transfer_uuid").toString();if(!selected.contains(key))continue;if(db.queryForObject("SELECT COUNT(*) FROM sales_transfers WHERE transfer_uuid=?",Integer.class,key)>0)throw new Api.Problem(409,"Phiếu "+item.get("source_code")+" đã nhận; chưa nhập thêm phiếu nào");try{String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(item)));db.update("INSERT INTO sales_transfers(transfer_uuid,payload_hash,payload) VALUES(?,?,?)",key,hash,json.writeValueAsString(item));}catch(java.security.NoSuchAlgorithmException|java.io.IOException e){throw new Api.Problem(500,"Không lưu được thông tin chống trùng");}core.audit(actor,"IMPORT_SALES","database",0);count++;}return Map.of("imported",count,"stock_changed",false,"unpriced",true);
 }
 @GetMapping("/incoming") @Transactional(readOnly=true) public Object incoming(@RequestHeader("Authorization") String token){access(token);var result=new ArrayList<Map<String,Object>>();for(var row:db.queryForList("SELECT * FROM sales_transfers ORDER BY created_at DESC")){var item=read(row);item.put("sale_id",row.get("SALE_ID"));item.put("received_at",row.get("CREATED_AT"));item.put("priced",row.get("SALE_ID")!=null);result.add(item);}return result;}
 Map<String,Object> read(Map<String,Object> row){try{return json.readValue(db.queryForObject("SELECT payload FROM sales_transfers WHERE transfer_uuid=?",String.class,row.get("TRANSFER_UUID")),new com.fasterxml.jackson.core.type.TypeReference<LinkedHashMap<String,Object>>(){});}catch(Exception e){throw new Api.Problem(500,"Không đọc được thông tin phiếu đã nhận");}}
 @PostMapping("/price/{key}") @Transactional public Object price(@RequestHeader("Authorization") String token,@PathVariable String key,@RequestBody Map<String,Object> body){access(token);var records=db.queryForList("SELECT * FROM sales_transfers WHERE transfer_uuid=? FOR UPDATE",key);if(records.isEmpty())throw new Api.Problem(404,"Không tìm thấy phiếu nhà máy đã nhận");var record=records.getFirst();if(record.get("SALE_ID")!=null)throw new Api.Problem(409,"Phiếu đã có giá bán; anh sửa trong báo cáo doanh số");var item=read(record);var sale=map(item.get("sale"));for(String field:List.of("channel","party_code","party_name","phone","province","sale_date","transport_cost","transport_fee"))if(body.containsKey(field))sale.put(field,body.get(field));var originals=core.lines(item,"lines");var inputs=core.lines(body,"lines");if(originals.size()!=inputs.size())throw new Api.Problem(400,"Điền giá cho đầy đủ các dòng đã nhận");for(int i=0;i<originals.size();i++){var line=originals.get(i);var value=inputs.get(i);line.put("unit_price",value.get("unit_price"));line.put("discount",value.getOrDefault("discount",0));line.put("support",value.getOrDefault("support",0));if(value.containsKey("factory_unit_cost"))line.put("factory_unit_cost",value.get("factory_unit_cost"));}item.put("entries",List.of());validate(Map.of("format","vinhkhang-sales-transfer","version",1,"sales",List.of(item)));var actor=core.admin(token);
 long id=core.insert("INSERT INTO revenue_sales(source_type,source_id,source_detached,source_code,channel,party_code,party_name,phone,province,sale_date,transport_cost,transport_fee,created_by) VALUES('VEHICLE',?,TRUE,?,?,?,?,?,?,?,?,?,?)",-System.nanoTime(),item.get("source_code"),sale.get("channel"),sale.get("party_code"),sale.get("party_name"),sale.get("phone"),sale.get("province"),RevenueReports.day(sale.get("sale_date")),SalesFlow.amount(sale,"transport_cost"),SalesFlow.amount(sale,"transport_fee"),actor.id());db.update("UPDATE revenue_sales SET source_id=-id WHERE id=?",id);int index=0;for(var line:originals)db.update("INSERT INTO revenue_lines(sale_id,members,item_code,item_name,category,quantity,unit_price,factory_unit_cost,discount,support,item_unit) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,Integer.toString(++index),line.get("item_code"),line.get("item_name"),line.get("category"),core.dec(line,"quantity"),RevenueReports.money(line,"unit_price",false),Costing.cost(line,"factory_unit_cost"),SalesFlow.amount(line,"discount"),SalesFlow.amount(line,"support"),line.get("item_unit"));db.update("UPDATE sales_transfers SET sale_id=? WHERE transfer_uuid=?",id,key);core.audit(actor,"PRICE_FACTORY_SALES","salesreport",id);return Map.of("id",id,"stock_changed",false);
 }

}

